<template><ion-page><ion-header><ion-toolbar><ion-title><span class="toolbar-page-title">Calendário acadêmico</span><span class="toolbar-brand-right">Task<span>Edu</span></span></ion-title></ion-toolbar></ion-header><ion-content><main class="page-container calendar-page"><header class="simple-heading"><p class="section-kicker">AGENDA MENSAL</p><h1>Calendário acadêmico</h1><p>Selecione uma data para visualizar os compromissos.</p></header><section class="calendar-layout"><div class="calendar-card"><div class="calendar-controls"><ion-button fill="clear" aria-label="Mês anterior" @click="mudarMes(-1)"><ion-icon slot="icon-only" :icon="chevronBackOutline"/></ion-button><h2>{{tituloMes}}</h2><ion-button fill="clear" aria-label="Próximo mês" @click="mudarMes(1)"><ion-icon slot="icon-only" :icon="chevronForwardOutline"/></ion-button></div><div class="weekdays"><span v-for="dia in ['D','S','T','Q','Q','S','S']" :key="dia">{{dia}}</span></div><div class="calendar-grid"><button v-for="dia in dias" :key="dia.chave" :disabled="!dia.data" :class="{selected:dia.data&&mesmoDia(dia.data,selecionada),hasTasks:dia.total}" @click="dia.data&&(selecionada=dia.data)"><span>{{dia.data?.getDate()}}</span><i v-if="dia.total">{{dia.total}}</i></button></div></div><aside><p class="section-kicker">{{dataSelecionada}}</p><h2>Compromissos do dia</h2><div v-if="!doDia.length" class="mini-empty">Nenhuma atividade nesta data.</div><AtividadeCard v-for="item in doDia" :key="item.id" :atividade="item"/></aside></section></main></ion-content><BottomNav tipo="aluno"/></ion-page></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { IonButton,IonContent,IonHeader,IonIcon,IonPage,IonTitle,IonToolbar } from '@ionic/vue';import { chevronBackOutline,chevronForwardOutline } from 'ionicons/icons';import AtividadeCard from '../components/AtividadeCard.vue';import BottomNav from '../components/BottomNav.vue';import { listarAtividadesPorTurma } from '../services/atividades.service';import { getUsuarioAtual } from '../services/auth.service';import type { Atividade } from '../types';import { mesmoDia } from '../utils/datas';interface DiaCalendario{chave:string;data:Date|null;total:number}const usuario=getUsuarioAtual(),atividades=ref<Atividade[]>([]),mes=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1)),selecionada=ref(new Date());const tituloMes=computed(()=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(mes.value));const dataSelecionada=computed(()=>new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(selecionada.value));const doDia=computed(()=>atividades.value.filter(a=>mesmoDia(a.dataEntrega.toDate(),selecionada.value)));const dias=computed<DiaCalendario[]>(()=>{const inicio=mes.value.getDay(),total=new Date(mes.value.getFullYear(),mes.value.getMonth()+1,0).getDate();const vazios:DiaCalendario[]=[...Array(inicio)].map((_,i)=>({chave:`v${i}`,data:null,total:0}));const datas:DiaCalendario[]=[...Array(total)].map((_,i)=>{const data=new Date(mes.value.getFullYear(),mes.value.getMonth(),i+1);return{chave:String(i),data,total:atividades.value.filter(a=>mesmoDia(a.dataEntrega.toDate(),data)).length}});return [...vazios,...datas]});function mudarMes(delta:number){mes.value=new Date(mes.value.getFullYear(),mes.value.getMonth()+delta,1);selecionada.value=new Date(mes.value)}onMounted(async()=>{if(usuario.value?.turma)atividades.value=await listarAtividadesPorTurma(usuario.value.turma)});</script>
